export async function chargeOrder(order: Order): Promise<PaymentReceipt> {
  return tracer.startActiveSpan('payment.charge', async (span) => {
    span.setAttribute('order.id', order.id);
    const receipt = await paymentClient.charge(order);
    span.end();
    return receipt;
  });
}

const receiptsByOrder = new Map<string, PaymentReceipt>();

export async function confirmOrder(orderId: string): Promise<void> {
  const receipt = await paymentClient.capture(orderId);
  receiptsByOrder.set(orderId, receipt); // used to answer retries quickly
  await ordersRepository.markPaid(orderId, receipt.id);
}

